import static org.junit.Assert.assertEquals;

/**
 * Unit tests for org.mockito.Matchers.anyByte()
 */
public class Matchers_anyByte_TriageGen1Test {

    @Test
    public void testAnyByteReturnsZero() {
        // The implementation of anyByte() calls reportMatcher(Any.ANY).returnZero()
        // For a byte, returnZero() should return (byte) 0.
        byte result = Matchers.anyByte();
        assertEquals((byte) 0, result);
    }
}
